args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?spouse ?spouseLabel WHERE {
  ?person rdfs:label "Elisa Godinez Gomez de Batista"@en .
  OPTIONAL { ?person dbo:spouse ?spouse . }
  OPTIONAL { ?person dbp:spouse ?spouse . }
  OPTIONAL { ?person dbp:husband ?spouse . }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(lang(?spouseLabel) = 'en') }
} LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?label ?spouse ?spouseLabel WHERE {
  ?person rdfs:label ?label .
  FILTER(langMatches(lang(?label), "en") || lang(?label) = "")
  FILTER regex(str(?label), "Elisa God", "i") .
  OPTIONAL { ?person dbo:spouse ?spouse . }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(lang(?spouseLabel) = 'en') }
} LIMIT 50

